App.register({group:'overview',label:'指挥台',icon:'◫',routes:[{path:'overview/home',title:'工作总览',icon:'◫',permission:'overview',render(){
 const t=App.tenant(),ps=App.accessibleProjects(),active=ps.filter(p=>p.status==='制作中').length,pending=ps.filter(p=>p.status.includes('审核')||p.status.includes('异常')),delivered=ps.filter(p=>p.status==='已交付').length;
 const tasks=pending.map(p=>{const exception=p.status.includes('异常'),target=exception?'pipeline/exceptions':p.status.includes('剧本')?'studio/script-review':'delivery/review';return `<div class="callout ${exception?'section-gap':''}"><div class="callout-icon">${exception?'!':'✳'}</div><div><strong>${exception?'生产异常':'待人工审核'} · ${UI.esc(p.title)}</strong><p>${exception?'当前项目存在暂停的生产任务，需要选择恢复策略。':'当前项目存在待确认的剧本或成片审核节点。'}</p><div class="section-gap">${`<button class="btn btn-sm btn-primary" data-action="project:task" data-id="${UI.esc(p.id)}" data-route="${target}">${exception?'处理异常':'进入审核'}</button>`}</div></div></div>`;}).join('');
 const taskContent=tasks||UI.empty('当前没有待决事项','当前授权项目中没有需要人工处理的审核或生产异常。');
 const rows=ps.slice(0,5).map(p=>`<tr><td><div class="entity"><div class="entity-mark">${UI.esc(p.title.slice(0,1))}</div><div><div class="entity-name">${UI.esc(p.title)}</div><div class="entity-meta mono">${UI.esc(p.id)}</div></div></div></td><td><div style="width:85px">${UI.progress(Math.round((p.done||0)/Math.max(p.episodes||1,1)*100),'')}</div></td><td>${UI.esc(p.stage||'待启动')}</td><td>${UI.tag(p.status,p.status==='已交付'?'green':p.status.includes('异常')?'red':p.status.includes('审核')?'orange':'blue')}</td><td>${`<button class="btn btn-sm" data-action="project:open" data-id="${UI.esc(p.id)}">打开项目</button>`}</td></tr>`);
 return UI.page('CONTROL ROOM / 01','生产指挥台','企业生产状态、待决事项与当前身份获授权的项目入口。',DB.state.identity==='auditor'?'':UI.btn('＋ 新建项目','project:new','btn-lime'),`
 <div class="hero"><div class="hero-kicker">YOUR PRODUCTION SPACE / ${UI.esc(t?.code||'NO WORKSPACE')}</div><h2>让创作想法，成为可交付的作品。</h2><p>AI 承担专业生产执行，员工负责创作方向、剧本确认、异常决策与最终成片审核。当前工作空间：${UI.esc(t?.name||'未选择租户')}。</p><div class="hero-actions">${DB.state.identity==='auditor'?'':UI.btn('开始一个新项目','project:new','btn-lime')}${UI.btn('查看生产流水线','go:pipeline/board','btn')}</div></div>
 <div class="grid grid-4 section-gap">${UI.metric('授权项目',ps.length,'当前身份可访问的项目','▣')}${UI.metric('正在生产',active,'AI 生产状态','◌')}${UI.metric('待人工决策',pending.length,'剧本 / 成片审核与异常处置','!')}${UI.metric('已交付作品',delivered,'当前授权范围内的正式交付','↗')}</div>
 <div class="grid grid-2 section-gap"><div class="card"><div class="card-head"><div><div class="card-title">项目生产动态</div><div class="card-sub">当前工作空间 · 最近更新</div></div><a class="small muted" href="#/workspace/projects">全部项目 →</a></div>${UI.table(['项目 / 编号','进度','当前阶段','状态','操作'],rows)}</div><div class="card"><div class="card-head"><div><div class="card-title">需要你确认的事项</div><div class="card-sub">只在人工决策节点介入</div></div>${UI.tag(pending.length+' 项待处理',pending.length?'orange':'green')}</div>${taskContent}</div></div>
 <div class="grid grid-3 section-gap"><div class="card"><div class="card-title">AI 生产能力状态</div><div class="kpi-line"><span>创意 / 剧本</span>${UI.tag('演示可用','green')}</div><div class="kpi-line"><span>视觉 / 分镜</span>${UI.tag('演示可用','green')}</div><div class="kpi-line"><span>视频生成</span>${UI.tag('演示队列','orange')}</div><div class="kpi-line"><span>音频 / 后期</span>${UI.tag('演示可用','green')}</div></div><div class="card"><div class="card-title">授权项目交付状态</div>${UI.chart(ps.slice(0,7).map(p=>Math.round((p.done||0)/Math.max(p.episodes||1,1)*100)),ps.slice(0,7).map((p,i)=>'P'+(i+1)))}<div class="tiny muted section-gap">按当前授权项目的完成集数比例展示；仅为演示数据。</div></div><div class="card"><div class="card-title">生产纪律</div><p class="small muted" style="line-height:1.8">项目、任务、素材、成本和成片均绑定租户。跨租户查看必须经过授权，员工离职不影响项目资产归属。</p>${UI.btn('查看审计记录','go:platform/audit','btn-sm')}</div></div>`);
}}]});